import { cn } from "@/lib/utils";
import { AnimatedCounter } from "../AnimatedCounter";
import { ShieldAlert, Scale, Network, AlertTriangle } from "lucide-react";

interface SlideProps {
  isActive: boolean;
}

const tierProblems = [
  {
    icon: Scale,
    title: "Tier I: No AI Governance",
    stat: "$15B",
    desc: "Enterprises deploying AI agents have zero post-hoc audit capability. EU AI Act enforcement begins 2025–2026. Compliance buyers cannot prove their AI behaved correctly.",
    color: "text-primary",
    border: "border-t-primary",
  },
  {
    icon: ShieldAlert,
    title: "Tier II: Unvalidated AI Execution",
    stat: "60%",
    desc: "At 95% per-step accuracy, a 10-step AI process has only 60% reliability. No deterministic runtime exists. Failed attempts are discarded as waste—$47 avg cost per failed call.",
    color: "text-accent",
    border: "border-t-accent",
  },
  {
    icon: Network,
    title: "Tier III: Security Disclosure Crisis",
    stat: "$2B",
    desc: "Bug bounty market has no actuarial basis, no chain-of-custody, no neutral halt authority. Researchers face coercion. Vendors dispute timelines. Patches collide without sequencing.",
    color: "text-secondary",
    border: "border-t-secondary",
  },
];

export function ProblemSlide({ isActive }: SlideProps) {
  return (
    <div className="space-y-6">
      <div
        className={cn("text-center space-y-2", isActive && "animate-fade-in")}
      >
        <h2 className="text-5xl font-bold">
          The <span className="gradient-text">$58B</span> Trust Deficit
        </h2>
        <p className="text-xl text-muted-foreground">
          Three converging crises that demand a new infrastructure layer
        </p>
      </div>

      <div
        className={cn(
          "grid grid-cols-3 gap-4",
          isActive && "animate-fade-in"
        )}
        style={{ animationDelay: "0.2s", opacity: isActive ? undefined : 0 }}
      >
        {tierProblems.map((tier, i) => (
          <div
            key={tier.title}
            className={cn(
              "glass-card rounded-2xl p-6 border-t-4 flex flex-col",
              tier.border,
              isActive && "animate-scale-in"
            )}
            style={{ animationDelay: `${0.3 + i * 0.15}s`, opacity: isActive ? undefined : 0 }}
          >
            <div className="flex items-center gap-3 mb-4">
              <tier.icon className={cn("w-6 h-6", tier.color)} />
              <h3 className="text-lg font-bold">{tier.title}</h3>
            </div>
            <div className={cn("text-4xl font-black mb-3", tier.color)}>{tier.stat}</div>
            <p className="text-sm text-muted-foreground leading-relaxed">{tier.desc}</p>
          </div>
        ))}
      </div>

      <div
        className={cn(
          "glass-card rounded-2xl p-6",
          isActive && "animate-fade-in"
        )}
        style={{ animationDelay: "0.6s", opacity: isActive ? undefined : 0 }}
      >
        <h3 className="text-xl font-semibold mb-4 flex items-center gap-3">
          <AlertTriangle className="w-6 h-6 text-destructive" />
          The Brutal Math of AI Reliability
        </h3>
        <div className="grid grid-cols-3 gap-6">
          {[
            { steps: 5, reliability: 77, color: "text-success" },
            { steps: 10, reliability: 60, color: "text-accent" },
            { steps: 20, reliability: 36, color: "text-destructive" },
          ].map((item, i) => (
            <div
              key={item.steps}
              className="text-center p-4 rounded-xl bg-muted/30 border border-border/50"
            >
              <div className="text-sm text-muted-foreground mb-1">{item.steps}-Step Process</div>
              <div className={cn("text-5xl font-bold", item.color)}>
                <AnimatedCounter value={item.reliability} suffix="%" isActive={isActive} duration={1500 + i * 300} />
              </div>
              <div className="text-xs text-muted-foreground mt-1">End-to-End Reliability</div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

