import { cn } from "@/lib/utils";
import { Scale, Cpu, Network, Check, X, AlertTriangle, TrendingUp } from "lucide-react";

interface SlideProps {
  isActive: boolean;
}

const tiers = [
  { name: "AI Policy Guardrails", id: "guardrails", icon: Scale, color: "text-primary", border: "border-primary/30" },
  { name: "Deterministic AI Validation", id: "validation", icon: Cpu, color: "text-accent", border: "border-accent/30" },
  { name: "Security Exploit Resolution", id: "security", icon: Network, color: "text-secondary", border: "border-secondary/30" },
];

const competitors = [
  {
    name: "KNIRV",
    isOurs: true,
    guardrails: true,
    validation: true,
    security: true,
    moat: "Only full-stack AI trust layer",
  },
  {
    name: "ASI Alliance",
    guardrails: false,
    validation: false,
    security: false,
    moat: "Speculative tokens, no enterprise validation",
  },
  {
    name: "ChainGPT",
    guardrails: false,
    validation: false,
    security: false,
    moat: "Consumer AI, no audit infrastructure",
  },
  {
    name: "LangSmith / Humanloop",
    guardrails: "partial",
    validation: false,
    security: false,
    moat: "Post-hoc observability, no enforcement",
  },
  {
    name: "Guardrails AI",
    guardrails: true,
    validation: false,
    security: false,
    moat: "App-layer only, no kernel telemetry",
  },
  {
    name: "HackerOne / Bugcrowd",
    guardrails: false,
    validation: false,
    security: "partial",
    moat: "Human-mediated, no chain-of-custody",
  },
];

function Cell({ value }: { value: boolean | "partial" | string }) {
  if (value === true) return <Check className="w-5 h-5 mx-auto text-success" />;
  if (value === "partial") return <AlertTriangle className="w-5 h-5 mx-auto text-warning" />;
  return <X className="w-5 h-5 mx-auto text-destructive" />;
}

export function CompetitiveSlide({ isActive }: SlideProps) {
  return (
    <div className="space-y-6">
      <div className={cn("text-center space-y-2", isActive && "animate-fade-in")}>
        <h2 className="text-5xl font-bold">
          <span className="gradient-text">Competitive Moat</span>
        </h2>
        <p className="text-xl text-muted-foreground">No competitor spans all 3 tiers. KNIRV owns the intersection.</p>
      </div>

      <div
        className={cn(
          "glass-card rounded-2xl overflow-hidden",
          isActive && "animate-fade-in"
        )}
        style={{ animationDelay: "0.2s", opacity: isActive ? undefined : 0 }}
      >
        <table className="w-full">
          <thead>
            <tr className="border-b border-border">
              <th className="p-3 text-left font-semibold text-sm">Platform</th>
              {tiers.map((t) => (
                <th key={t.id} className={cn("p-3 text-center font-semibold text-xs", t.color)}>
                  <div className="flex items-center justify-center gap-1.5">
                    <t.icon className="w-4 h-4" />
                    {t.name}
                  </div>
                </th>
              ))}
              <th className="p-3 text-left font-semibold text-sm">Moat Analysis</th>
            </tr>
          </thead>
          <tbody>
            {competitors.map((comp) => (
              <tr
                key={comp.name}
                className={cn(
                  "border-b border-border/50",
                  comp.isOurs && "bg-primary/10"
                )}
              >
                <td className={cn(
                  "p-3 font-medium",
                  comp.isOurs && "text-primary font-bold"
                )}>
                  {comp.name}
                </td>
                <td className="p-3"><Cell value={comp.guardrails} /></td>
                <td className="p-3"><Cell value={comp.validation} /></td>
                <td className="p-3"><Cell value={comp.security} /></td>
                <td className="p-3 text-xs text-muted-foreground">{comp.moat}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div
        className={cn(
          "grid grid-cols-3 gap-4",
          isActive && "animate-fade-in"
        )}
        style={{ animationDelay: "0.4s", opacity: isActive ? undefined : 0 }}
      >
        <div className="glass-card rounded-2xl p-5 border-t-4 border-t-primary">
          <Scale className="w-8 h-8 text-primary mb-2" />
          <h3 className="font-bold text-sm mb-1">No AI Governance competitor</h3>
          <p className="text-xs text-muted-foreground">
            .has kernel-level eBPF + blockchain anchoring. OPA, Sentinel are policy-only.
          </p>
        </div>
        <div className="glass-card rounded-2xl p-5 border-t-4 border-t-accent">
          <Cpu className="w-8 h-8 text-accent mb-2" />
          <h3 className="font-bold text-sm mb-1">No MLOps competitor</h3>
          <p className="text-xs text-muted-foreground">
            does pre-enforcement. LangSmith, Weave do post-hoc. Fundamental architectural difference.
          </p>
        </div>
        <div className="glass-card rounded-2xl p-5 border-t-4 border-t-secondary">
          <Network className="w-8 h-8 text-secondary mb-2" />
          <h3 className="font-bold text-sm mb-1">No security platform</h3>
          <p className="text-xs text-muted-foreground">
            combines chain-of-custody + andon cord + blind peer review. HackerOne is a marketplace, not infrastructure.
          </p>
        </div>
      </div>

      <div
        className={cn(
          "text-center p-5 rounded-2xl bg-gradient-to-r from-primary/20 via-accent/10 to-secondary/20 border border-primary/30",
          isActive && "animate-fade-in"
        )}
        style={{ animationDelay: "0.5s", opacity: isActive ? undefined : 0 }}
      >
        <h3 className="text-xl font-bold mb-1">The "Triple Coverage" Moat</h3>
        <p className="text-sm text-muted-foreground">
          Each tier is independently defensible. Together, they create a cross-platform switching cost no competitor can match.{" "}
          <span className="text-primary font-semibold">Enter Tier I → upsell Tier II → expand to Tier III.</span>
        </p>
      </div>
    </div>
  );
}

