    combinedData.map((d) => ({ ...d, total: 0, guardrails: 0, validation: 0, security: 0 }))
  );

  useEffect(() => {
    if (!isActive) {
      setAnimatedData(combinedData.map((d) => ({ ...d, total: 0, guardrails: 0, validation: 0, security: 0 })));
      return;
    }

    const timeout = setTimeout(() => {
      combinedData.forEach((point, index) => {
        setTimeout(() => {
          setAnimatedData((prev) =>
            prev.map((d, i) => (i <= index ? { ...d, ...combinedData[i] } : d))
          );
        }, index * 300);
      });
    }, 500);

    return () => clearTimeout(timeout);
  }, [isActive]);

  return (
    <div className="space-y-6">
      <div className={cn("text-center space-y-2", isActive && "animate-fade-in")}>
        <h2 className="text-5xl font-bold">
          <span className="gradient-text">Financial Projections</span>
        </h2>
        <p className="text-xl text-muted-foreground">$5M → $550M · $58B TAM · Path to $5-10B exit</p>
      </div>

      <div className="grid grid-cols-5 gap-6">
        <div
          className={cn(
            "col-span-3 glass-card rounded-2xl p-5",
            isActive && "animate-slide-in-left"
          )}
          style={{ animationDelay: "0.2s", opacity: isActive ? undefined : 0 }}
        >
          <h3 className="text-sm font-bold mb-3">5-Year Revenue by Tier ($M)</h3>
          <div className="h-56">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={animatedData}>
                <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
                <XAxis dataKey="year" stroke="hsl(var(--muted-foreground))" fontSize={12} />
                <YAxis stroke="hsl(var(--muted-foreground))" fontSize={12} tickFormatter={(v) => `$${v}M`} />
                <Tooltip
                  contentStyle={{
                    backgroundColor: "hsl(var(--card))",
                    border: "1px solid hsl(var(--border))",
                    borderRadius: "8px",
                  }}
                  formatter={(value: number, name: string) => [`$${value}M`, name]}
                />
                <Legend />
                <Bar dataKey="guardrails" name="Tier I: Guardrails" stackId="a" fill="hsl(var(--primary))" />
                <Bar dataKey="validation" name="Tier II: Validation" stackId="a" fill="hsl(var(--accent))" />
                <Bar dataKey="security" name="Tier III: Security" stackId="a" fill="hsl(var(--secondary))" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div
          className={cn(
            "col-span-2 space-y-3",
            isActive && "animate-slide-in-right"
          )}
          style={{ animationDelay: "0.3s", opacity: isActive ? undefined : 0 }}
        >
          <div className="glass-card rounded-2xl p-4">
            <div className="text-xs text-muted-foreground mb-1">Year 5 Revenue</div>
            <div className="text-3xl font-bold text-primary">
              $<AnimatedCounter value={550} isActive={isActive} duration={2000} />M
            </div>
          </div>
          <div className="glass-card rounded-2xl p-4">
            <div className="text-xs text-muted-foreground mb-1">Target Exit</div>
            <div className="text-3xl font-bold text-secondary">$5B – $10B</div>
          </div>
          <div className="glass-card rounded-2xl p-4">
            <div className="text-xs text-muted-foreground mb-1">Break-even</div>
            <div className="text-3xl font-bold text-accent">24–36 months</div>
          </div>
          <div className="glass-card rounded-2xl p-4">
            <div className="text-xs text-muted-foreground mb-1">Token Sale (Q4 2026)</div>
            <div className="text-3xl font-bold text-success">
              $<AnimatedCounter value={100} isActive={isActive} duration={2000} />M
            </div>
          </div>
        </div>
      </div>

      <div
        className={cn(
          "grid grid-cols-5 gap-3",
          isActive && "animate-fade-in"
        )}
        style={{ animationDelay: "0.5s", opacity: isActive ? undefined : 0 }}
      >
        {combinedData.map((point, index) => (
          <div
            key={point.year}
            className={cn(
              "text-center p-3 rounded-xl",
              "bg-gradient-to-br from-muted/50 to-muted/20",
              "border border-border/50"
            )}
          >
            <div className="text-xs font-bold text-muted-foreground">{point.year}</div>
            <div className="text-lg font-bold gradient-text">{point.label}</div>
            <div className="text-[10px] text-muted-foreground mt-0.5">
              {index === 0 && "Foundation"}
              {index === 1 && "Growth"}
              {index === 2 && "Enterprise"}
              {index === 3 && "Scale"}
              {index === 4 && "Domination"}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback } from "react";
import { cn } from "@/lib/utils";
import { SlideNavigation } from "./SlideNavigation";
import { SlideProgress } from "./SlideProgress";
import { HeroSlide } from "./slides/HeroSlide";
import { ProblemSlide } from "./slides/ProblemSlide";
import { TierOverviewSlide } from "./slides/TierOverviewSlide";
import { TierISlide } from "./slides/TierISlide";
import { TierIISlide } from "./slides/TierIISlide";
import { TierIIISlide } from "./slides/TierIIISlide";
import { RevenueSlide } from "./slides/RevenueSlide";
import { CompetitiveSlide } from "./slides/CompetitiveSlide";
import { FinancialsSlide } from "./slides/FinancialsSlide";
import { InvestmentSlide } from "./slides/InvestmentSlide";
import { ClosingSlide } from "./slides/ClosingSlide";
import { KeyboardHint } from "./KeyboardHint";

export interface SlideConfig {
  id: string;
  title: string;
  module: string;
  component: React.ComponentType<{ isActive: boolean }>;
}

const slides: SlideConfig[] = [
  { id: "hero", title: "KNIRV", module: "Introduction", component: HeroSlide },
  { id: "problem", title: "The $58B Problem", module: "Introduction", component: ProblemSlide },
  { id: "tier-overview", title: "3 Tiers at a Glance", module: "Products", component: TierOverviewSlide },
  { id: "tier-i", title: "Tier I: Guardrails Engine", module: "Products", component: TierISlide },
  { id: "tier-ii", title: "Tier II: AI Validation", module: "Products", component: TierIISlide },
  { id: "tier-iii", title: "Tier III: Security Platform", module: "Products", component: TierIIISlide },
  { id: "revenue", title: "Revenue Engine", module: "Business", component: RevenueSlide },
  { id: "competitive", title: "Competitive Moat", module: "Advantage", component: CompetitiveSlide },
  { id: "financials", title: "Financial Projections", module: "Business", component: FinancialsSlide },
  { id: "investment", title: "Investment Structure", module: "Investment", component: InvestmentSlide },
  { id: "closing", title: "The Ask", module: "Closing", component: ClosingSlide },
];

export function PitchDeck() {
  const [currentSlide, setCurrentSlide] = useState(0);
  const [isTransitioning, setIsTransitioning] = useState(false);
  const [showNav, setShowNav] = useState(true);

  const navigateToSlide = useCallback((index: number) => {
    if (index < 0 || index >= slides.length || isTransitioning) return;
    setIsTransitioning(true);
    setCurrentSlide(index);
    setTimeout(() => setIsTransitioning(false), 600);
  }, [isTransitioning]);

  const nextSlide = useCallback(() => {
    navigateToSlide(currentSlide + 1);
  }, [currentSlide, navigateToSlide]);

  const prevSlide = useCallback(() => {
    navigateToSlide(currentSlide - 1);
  }, [currentSlide, navigateToSlide]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "ArrowRight" || e.key === " " || e.key === "Enter") {
        e.preventDefault();
        nextSlide();
      } else if (e.key === "ArrowLeft" || e.key === "Backspace") {
        e.preventDefault();
        prevSlide();
      } else if (e.key === "Escape") {
        setShowNav((prev) => !prev);
      } else if (e.key === "Home") {
        navigateToSlide(0);
      } else if (e.key === "End") {
        navigateToSlide(slides.length - 1);
      } else if (e.key >= "1" && e.key <= "9") {
        const slideIndex = parseInt(e.key) - 1;
        if (slideIndex < slides.length) {
          navigateToSlide(slideIndex);
        }
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [nextSlide, prevSlide, navigateToSlide]);

  const CurrentSlideComponent = slides[currentSlide].component;

  return (
    <div className="relative h-screen w-screen overflow-hidden bg-background">
      <div className="absolute inset-0 bg-gradient-to-br from-background via-background to-muted/30" />
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none">
        <div className="absolute -top-1/2 -left-1/2 w-full h-full bg-gradient-to-br from-primary/10 via-transparent to-transparent rounded-full blur-3xl" />
        <div className="absolute -bottom-1/2 -right-1/2 w-full h-full bg-gradient-to-tl from-accent/10 via-transparent to-transparent rounded-full blur-3xl" />
      </div>

      <SlideNavigation
        slides={slides}
        currentSlide={currentSlide}
        onNavigate={navigateToSlide}
        isVisible={showNav}
      />

      <div
        className={cn(
          "relative h-full transition-all duration-300",
          showNav ? "ml-64" : "ml-0"
        )}
      >
        <SlideProgress
          current={currentSlide}
          total={slides.length}
        />

        <div className="h-full flex items-center justify-center p-8">
          <div
            className={cn(
              "w-full max-w-6xl",
              isTransitioning && "pointer-events-none"
            )}
          >
            <CurrentSlideComponent isActive={!isTransitioning} />
          </div>
        </div>

        <KeyboardHint />

        <button
          onClick={prevSlide}
          disabled={currentSlide === 0}
          className={cn(
            "absolute left-4 top-1/2 -translate-y-1/2 p-3 rounded-full",
            "bg-card/80 backdrop-blur-sm border border-border/50",
            "text-foreground hover:bg-primary hover:text-primary-foreground",
            "transition-all duration-200",
            "disabled:opacity-30 disabled:cursor-not-allowed disabled:hover:bg-card/80 disabled:hover:text-foreground"
          )}
        >
          <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
          </svg>
        </button>

        <button
          onClick={nextSlide}
          disabled={currentSlide === slides.length - 1}
          className={cn(
            "absolute right-4 top-1/2 -translate-y-1/2 p-3 rounded-full",
            "bg-card/80 backdrop-blur-sm border border-border/50",
            "text-foreground hover:bg-primary hover:text-primary-foreground",
            "transition-all duration-200",
            "disabled:opacity-30 disabled:cursor-not-allowed disabled:hover:bg-card/80 disabled:hover:text-foreground"
          )}
        >
          <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
          </svg>
        </button>

        <div className="absolute bottom-4 right-4 text-sm text-muted-foreground font-mono">
          {String(currentSlide + 1).padStart(2, "0")} / {String(slides.length).padStart(2, "0")}
        </div>
      </div>
    </div>
  );
}

